package com.rusticcraft.publicmines.run;

import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.ResourceLocationException;
import net.minecraft.world.level.Level;

/**
 * An explicitly mine-owned axis-aligned block volume in one dimension.
 * These records are the cleanup/recovery boundary: nothing outside any
 * recorded volume may be cleared or regenerated by mine code.
 */
public record OwnedVolume(
        String label, ResourceKey<Level> dimension, BlockPos min, BlockPos max) {

    public boolean contains(Level level, BlockPos pos) {
        return level.dimension().equals(dimension) && contains(pos);
    }

    public boolean contains(BlockPos pos) {
        return pos.getX() >= min.getX() && pos.getX() <= max.getX()
                && pos.getY() >= min.getY() && pos.getY() <= max.getY()
                && pos.getZ() >= min.getZ() && pos.getZ() <= max.getZ();
    }

    public String describe() {
        return label + " " + dimension.location() + " ["
                + min.getX() + "," + min.getY() + "," + min.getZ() + "] to ["
                + max.getX() + "," + max.getY() + "," + max.getZ() + "]";
    }

    public CompoundTag save() {
        CompoundTag tag = new CompoundTag();
        tag.putString("label", label);
        tag.putString("dim", dimension.location().toString());
        tag.putIntArray("min", new int[] {min.getX(), min.getY(), min.getZ()});
        tag.putIntArray("max", new int[] {max.getX(), max.getY(), max.getZ()});
        return tag;
    }

    /** Loads a volume, or returns null for a malformed record so a corrupted
     * entry cannot crash the recovery-critical data load path. */
    public static OwnedVolume load(CompoundTag tag) {
        int[] min = tag.getIntArray("min");
        int[] max = tag.getIntArray("max");
        String dim = tag.getString("dim");
        if (min.length != 3 || max.length != 3 || dim.isEmpty()) {
            return null;
        }
        ResourceKey<Level> dimension;
        try {
            dimension = ResourceKey.create(
                    net.minecraft.core.registries.Registries.DIMENSION,
                    ResourceLocation.parse(dim));
        } catch (ResourceLocationException e) {
            return null;
        }
        return new OwnedVolume(
                tag.getString("label"), dimension,
                new BlockPos(min[0], min[1], min[2]),
                new BlockPos(max[0], max[1], max[2]));
    }
}
